<script setup lang="ts">
import { computed, nextTick, reactive, ref } from 'vue'
import { Pencil } from 'lucide-vue-next'
import Modal from './Modal.vue'
import ProjectMemberSelect from './ProjectMemberSelect.vue'
import DraftNotice from './DraftNotice.vue'
import ConflictNotice from './ConflictNotice.vue'
import { useConflict,useDraft } from '../drafts'
import { api, messageOf, notify, taskStatuses } from '../api'
import type { Task } from '../types'
type Field='name'|'assignee'|'plan_end'|'progress'|'status'
const props=defineProps<{task:Task;field:Field;label:string;readonly?:boolean}>();const emit=defineEmits<{updated:[task:Task]}>()
const editing=ref(false),saving=ref(false),error=ref(''),baseVersion=ref(props.task.version),form=reactive<Record<string,string|number>>({[props.field]:props.task[props.field],assignee_member_id:props.task.assignee_member_id||''}),input=ref<HTMLInputElement|HTMLSelectElement>(),conflictOpen=ref(false)
const memberPicker=ref<InstanceType<typeof ProjectMemberSelect>>()
const local=useDraft(()=>`tasks:${props.task.id}:inline:${props.field}`,form,()=>editing.value,()=>baseVersion.value),conflict=useConflict()
const value=computed(()=>form[props.field]);const dirty=computed(()=>String(value.value)!==String(props.task[props.field])||props.field==='assignee'&&form.assignee_member_id!==(props.task.assignee_member_id||''))
async function start(){if(props.readonly||saving.value)return;form[props.field]=props.task[props.field];form.assignee_member_id=props.task.assignee_member_id||'';baseVersion.value=props.task.version;error.value='';editing.value=true;await local.reset();await nextTick();if(props.field==='assignee')memberPicker.value?.focus();else input.value?.focus();if(input.value instanceof HTMLInputElement&&input.value.type==='text')input.value.select()}
function cancel(){if(saving.value)return;local.discard();editing.value=false;error.value='';conflict.clear();conflictOpen.value=false}
async function save(){if(!editing.value||saving.value||conflictOpen.value)return;if(!dirty.value){local.discard();editing.value=false;return}if(props.field==='name'&&!String(value.value).trim()){error.value='任务名称不能为空';input.value?.focus();return}if(props.field==='progress'&&(!Number.isInteger(Number(value.value))||Number(value.value)<0||Number(value.value)>100)){error.value='进度必须为 0–100 的整数';input.value?.focus();return}saving.value=true;error.value='';try{const task=await api<Task>(`/api/tasks/${props.task.id}`,{method:'PATCH',body:JSON.stringify({...(props.field==='assignee'?{assignee_member_id:form.assignee_member_id}:{[props.field]:props.field==='progress'?Number(value.value):value.value}),version:baseVersion.value})});local.discard();editing.value=false;emit('updated',task);notify(`${props.label}已保存`)}catch(e){local.persist();error.value=messageOf(e);if(await conflict.capture(e,`/api/tasks/${props.task.id}`,form))conflictOpen.value=true}finally{saving.value=false}}
function key(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Enter'&&!(event.target as HTMLElement|null)?.closest?.('button')){event.preventDefault()}else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();cancel()}}
defineExpose({canLeave:()=>!saving.value&&(!editing.value||local.canLeave())})
async function loadRemote(){const remote=conflict.current.value?.remote as unknown as Task;if(!remote)return;local.persist();baseVersion.value=remote.version;form[props.field]=remote[props.field];form.assignee_member_id=remote.assignee_member_id||'';emit('updated',remote);conflict.clear();conflictOpen.value=false;await local.reset();error.value='已载入数据库内容，原修改仍保留为草稿。'}
function keepLocal(){local.persist();conflict.clear();conflictOpen.value=false;error.value='本地修改已保留。请取消并重新编辑后，比较恢复草稿再保存。'}
</script>
<template><div v-if="editing" class="inline-edit" @keydown="key"><DraftNotice :value="local.available.value" :values="local.values.value" :error="local.storageError.value" :recovery="local.recovery.value" @select="local.select" @restore="local.restore" @force="local.restoreForced" @cancel-recovery="local.clearRecovery" @discard="local.discardAvailable"/><select v-if="field==='status'" ref="input" v-model="form[field]" :disabled="saving" :aria-label="label"><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select><ProjectMemberSelect v-else-if="field==='assignee'" ref="memberPicker" :label="label" :model-value="String(form.assignee_member_id||'')" :project-id="task.project_id" stable :legacy-name="String(form.assignee||'')" :disabled="saving" :manage="false" @update:model-value="form.assignee_member_id=$event" @chosen="form.assignee=$event?.name||''"/><input v-else ref="input" v-model="form[field]" :type="field==='plan_end'?'date':field==='progress'?'number':'text'" :min="field==='progress'?0:undefined" :max="field==='progress'?100:undefined" :maxlength="field==='name'?200:100" :disabled="saving" :aria-label="label"/><div class="inline-actions"><button type="button" class="text-button" :disabled="saving" @click="save">{{saving?'保存中…':'保存'}}</button><button type="button" class="text-button muted" :disabled="saving" @click="cancel">取消</button></div><p v-if="error" class="inline-error" role="alert">{{error}}</p><Modal :open="conflictOpen" :title="`${label}保存冲突`" wide @close="keepLocal"><div class="modal-body"><ConflictNotice :value="conflict.current.value" @keep="keepLocal" @reload="loadRemote"/></div></Modal></div><div v-else class="inline-value" @dblclick="start"><slot/><button v-if="!readonly" type="button" class="inline-edit-trigger" :aria-label="`编辑${task.name}的${label}`" :title="`编辑${label}，点击保存后生效，Esc取消`" @click="start"><Pencil :size="12"/></button></div></template>
